use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::time::{SystemTime, UNIX_EPOCH};

/// Token-based access control system for a document management service.
/// Tokens have scopes that limit which document collections they can access.

#[derive(Clone, Debug)]
pub struct Token {
    pub user_id: String,
    pub scopes: Vec<String>,
    pub issued_at: u64,
    pub expires_at: u64,
    pub max_depth: i32,  // Maximum directory depth the token allows (-1 = unlimited)
}

#[derive(Clone, Debug)]
pub struct Document {
    pub path: String,
    pub content: String,
    pub classification: String, // "public", "internal", "secret"
}

pub struct DocumentService {
    documents: Arc<RwLock<HashMap<String, Document>>>,
    tokens: Arc<RwLock<HashMap<String, Token>>>,
    access_log: Arc<RwLock<Vec<String>>>,
}

impl DocumentService {
    pub fn new() -> Self {
        DocumentService {
            documents: Arc::new(RwLock::new(HashMap::new())),
            tokens: Arc::new(RwLock::new(HashMap::new())),
            access_log: Arc::new(RwLock::new(Vec::new())),
        }
    }

    pub fn add_document(&self, path: String, content: String, classification: String) {
        let doc = Document { path: path.clone(), content, classification };
        let mut docs = self.documents.write().unwrap();
        docs.insert(path, doc);
    }

    pub fn issue_token(&self, user_id: String, scopes: Vec<String>, max_depth: i32, ttl_secs: u64) -> String {
        let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();
        let token = Token {
            user_id: user_id.clone(),
            scopes,
            issued_at: now,
            expires_at: now + ttl_secs,
            max_depth,
        };
        let token_id = format!("tok_{}_{}", user_id, now);
        let mut tokens = self.tokens.write().unwrap();
        tokens.insert(token_id.clone(), token);
        token_id
    }

    /// Compute the depth of a document path.
    /// e.g., "/public/reports/q1.txt" has depth 3
    fn compute_depth(path: &str) -> i32 {
        let normalized = path.trim_matches('/');
        if normalized.is_empty() {
            return 0;
        }
        normalized.split('/').count() as i32
    }

    /// Check if the token's scopes grant access to the given document path.
    /// A scope "public" grants access to paths starting with "/public/".
    /// A scope "*" grants access to all paths.
    fn scope_allows(token: &Token, doc_path: &str) -> bool {
        for scope in &token.scopes {
            if scope == "*" {
                return true;
            }
            // Scope "public" allows access to "/public/" prefix
            let scope_prefix = format!("/{}/", scope);
            if doc_path.starts_with(&scope_prefix) {
                return true;
            }
        }
        false
    }

    /// Validate that the requested path depth does not exceed token's max_depth.
    /// max_depth of -1 means unlimited access.
    /// Returns true if access is allowed.
    fn depth_allows(token: &Token, path: &str) -> bool {
        if token.max_depth == -1 {
            return true;
        }
        let depth = Self::compute_depth(path);
        // Check: document depth must not exceed the token's max_depth
        depth <= token.max_depth
    }

    /// Validate token is not expired
    fn is_token_valid(token: &Token) -> bool {
        let now = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();
        now < token.expires_at
    }

    /// Primary access control check combining all validations
    fn authorize(&self, token_id: &str, doc_path: &str) -> Result<Token, String> {
        let tokens = self.tokens.read().unwrap();
        let token = tokens.get(token_id)
            .ok_or_else(|| "Invalid token".to_string())?
            .clone();
        drop(tokens);

        // Check expiration
        if !Self::is_token_valid(&token) {
            return Err("Token expired".to_string());
        }

        // Check scope
        if !Self::scope_allows(&token, doc_path) {
            return Err("Scope does not permit access to this path".to_string());
        }

        // Check depth restriction
        if !Self::depth_allows(&token, doc_path) {
            return Err("Path depth exceeds token allowance".to_string());
        }

        Ok(token)
    }

    /// Retrieve a document with full authorization checks.
    /// Classification-based access: tokens with scope "*" can access "secret",
    /// others can only access "public" and "internal".
    pub fn get_document(&self, token_id: &str, doc_path: &str) -> Result<String, String> {
        // Normalize the path to prevent traversal
        let normalized = self.normalize_path(doc_path)?;

        // Perform authorization
        let token = self.authorize(token_id, &normalized)?;

        // Retrieve document
        let docs = self.documents.read().unwrap();
        let doc = docs.get(&normalized)
            .ok_or_else(|| "Document not found".to_string())?;

        // Classification check
        if doc.classification == "secret" && !token.scopes.contains(&"*".to_string()) {
            return Err("Insufficient clearance".to_string());
        }

        // Log access
        let mut log = self.access_log.write().unwrap();
        log.push(format!("ACCESS: user={} path={} class={}", token.user_id, normalized, doc.classification));

        Ok(doc.content.clone())
    }

    /// Normalize path: collapse redundant separators, resolve . and ..
    /// Reject paths that attempt to escape root.
    fn normalize_path(&self, path: &str) -> Result<String, String> {
        if path.contains('\0') {
            return Err("Invalid path: null byte".to_string());
        }

        let mut components: Vec<&str> = Vec::new();
        for component in path.split('/') {
            match component {
                "" | "." => continue,
                ".." => {
                    if components.is_empty() {
                        return Err("Path traversal detected".to_string());
                    }
                    components.pop();
                }
                c => components.push(c),
            }
        }

        if components.is_empty() {
            return Err("Empty path".to_string());
        }

        Ok(format!("/{}", components.join("/")))
    }

    /// Bulk retrieve: get multiple documents in one call.
    /// Applies same authorization to each path.
    pub fn get_documents_bulk(&self, token_id: &str, paths: &[&str]) -> Vec<Result<String, String>> {
        paths.iter().map(|p| self.get_document(token_id, p)).collect()
    }

    /// List documents accessible by a token within a given prefix
    pub fn list_documents(&self, token_id: &str, prefix: &str) -> Result<Vec<String>, String> {
        let normalized_prefix = self.normalize_path(prefix).unwrap_or_else(|_| "/".to_string());

        let tokens = self.tokens.read().unwrap();
        let token = tokens.get(token_id)
            .ok_or_else(|| "Invalid token".to_string())?
            .clone();
        drop(tokens);

        if !Self::is_token_valid(&token) {
            return Err("Token expired".to_string());
        }

        let docs = self.documents.read().unwrap();
        let mut results = Vec::new();

        for (path, _doc) in docs.iter() {
            if path.starts_with(&normalized_prefix) 
                && Self::scope_allows(&token, path)
                && Self::depth_allows(&token, path) {
                results.push(path.clone());
            }
        }

        Ok(results)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_access() {
        let svc = DocumentService::new();
        svc.add_document("/public/readme.txt".to_string(), "Hello World".to_string(), "public".to_string());
        let token = svc.issue_token("alice".to_string(), vec!["public".to_string()], 3, 3600);
        let result = svc.get_document(&token, "/public/readme.txt");
        assert_eq!(result.unwrap(), "Hello World");
    }

    #[test]
    fn test_scope_denied() {
        let svc = DocumentService::new();
        svc.add_document("/secret/plans.txt".to_string(), "Top Secret".to_string(), "secret".to_string());
        let token = svc.issue_token("bob".to_string(), vec!["public".to_string()], 3, 3600);
        let result = svc.get_document(&token, "/secret/plans.txt");
        assert!(result.is_err());
    }

    #[test]
    fn test_depth_restriction() {
        let svc = DocumentService::new();
        svc.add_document("/public/a/b/c/deep.txt".to_string(), "Deep".to_string(), "public".to_string());
        let token = svc.issue_token("carol".to_string(), vec!["public".to_string()], 2, 3600);
        let result = svc.get_document(&token, "/public/a/b/c/deep.txt");
        assert!(result.is_err());
    }

    #[test]
    fn test_traversal_blocked() {
        let svc = DocumentService::new();
        svc.add_document("/secret/plans.txt".to_string(), "Top Secret".to_string(), "secret".to_string());
        let token = svc.issue_token("eve".to_string(), vec!["public".to_string()], 3, 3600);
        let result = svc.get_document(&token, "/public/../secret/plans.txt");
        assert!(result.is_err());
    }

    #[test]
    fn test_unlimited_depth() {
        let svc = DocumentService::new();
        svc.add_document("/public/a/b/c/d/e/f.txt".to_string(), "Very Deep".to_string(), "public".to_string());
        let token = svc.issue_token("dave".to_string(), vec!["public".to_string()], -1, 3600);
        let result = svc.get_document(&token, "/public/a/b/c/d/e/f.txt");
        assert_eq!(result.unwrap(), "Very Deep");
    }
}
